seed_files.scripts/release.sh:
#!/usr/bin/env bash
# 릴리즈 스크립트 (중복 에러처리 — 리팩터링 대상)
set -u
VERSION="${1:-}"
[ -z "$VERSION" ] && { echo '사용: release.sh <version>'; exit 1; }
echo '[1/3] 테스트'; bash tests/test.sh; [ $? -ne 0 ] && { echo 실패; exit 1; }
echo '[2/3] 빌드'; mkdir -p dist && cp scripts/*.sh dist/; [ $? -ne 0 ] && { echo 실패; exit 1; }
echo '[3/3] 태그'; git tag "v$VERSION"; [ $? -ne 0 ] && { echo 실패; exit 1; }
echo "완료: v$VERSION"

seed_files.scripts/slug.sh:
#!/usr/bin/env bash
# 문자열 → URL 슬러그
slugify() { echo "$1" | tr '[:upper:]' '[:lower:]' | tr ' ' '-'; }
slugify "$1"
